}{
\begin{tikzpicture}

    % Vẽ tam giác ABC
    \coordinate [label=left:A] (A) at (0,0);
    \coordinate [label=right:B] (B) at (8,0);
    \coordinate [label=above:C] (C) at (2,1);

    % Đặt các góc và chiều cao
    \draw (A) -- (B) -- (C) -- cycle;

    % Vẽ chiều cao từ C tới AB
\draw (C) -- (2,0) coordinate (H);
\node[below] at (H) {H};
      % Vẽ dấu vuông tại điểm H
        \draw (2,0) rectangle +(0.1,0.1);
    % Nhãn chiều cao
    \draw[<-] (C) -- ($(C)!0.5!(H)$) node[midway, right] {$h$};

    % Vẽ các cung góc

    \node at ($(A)+(0.6,0.15)$) {$10^{\circ}$};


    \node at ($(B)+(-1.9,0.15)$) {$6^{\circ}$};

\end{tikzpicture}
}
\shortans{105}

\loigiai{
\begin{center}
\begin{tikzpicture}[scale=0.80, font=\footnotesize, line cap=round, line join=round]
\coordinate (A) at (0,0);
\coordinate (H) at (2.1,0);
\coordinate (B) at (4.8,0);
\coordinate (C) at (2.1,2.2);
\draw[thick] (A) -- (B) -- (C) -- cycle;
\draw[dashed, thick, red!75!black] (C) -- (H) node[midway, right] {$h$};
\draw[thin] ($(H)!0.2cm!(C)$) -- ($($(H)!0.2cm!(C)$)+($(H)!0.2cm!(B)$)-(H)$) -- ($(H)!0.2cm!(B)$);
\draw[blue!75!black, thin] let \p1 = ($(H)-(A)$), \p2 = ($(C)-(A)$) in ($(A) + ({atan2(\y1,\x1)}:0.58)$) arc ({atan2(\y1,\x1)}:{atan2(\y2,\x2)}:0.58);
\draw[blue!75!black, thin] let \p1 = ($(C)-(B)$), \p2 = ($(H)-(B)$) in ($(B) + ({atan2(\y1,\x1)}:0.62)$) arc ({atan2(\y1,\x1)}:{atan2(\y2,\x2)}:0.62);
\node[blue!75!black] at ($(A)+(23:0.95)$) {$10^\circ$};
\node[blue!75!black] at ($(B)+(160:1.0)$) {$6^\circ$};
\fill (A) circle (1.5pt) node[below left] {$A$};
\fill (H) circle (1.5pt) node[below] {$H$};
\fill (B) circle (1.5pt) node[below right] {$B$};
\fill (C) circle (1.5pt) node[above] {$C$};
\end{tikzpicture}
\end{center}
Ta có: $AH=h \cdot \cot{6^{\circ}}$, $BH=h \cdot \cot{10^{\circ}}$\\
$AB=AH+BH=h \cdot \cot{6^{\circ}} + h \cdot \cot{10^{\circ}} = h \left(\cot{6^{\circ}} +\cot{10^{\circ}} \right)$\\
$h= \dfrac{1,6}{ \cot{6^{\circ}} +  \cot{10^{\circ}}} \approx 0,1054km \approx 105m$
}\end{ex}
